int huffmanCost(const vector<int>& weights) {
    priority_queue<int, vector<int>, greater<int>> pq(weights.begin(), weights.end());
    int cost = 0;
    while (pq.size() > 1) {
        int a = pq.top(); pq.pop();
        int b = pq.top(); pq.pop();
        cost += a + b;
        pq.push(a + b);
    }
    return cost;
}

