vector<int> topoSort(const vector<vector<int>>& graph) {
    int n = graph.size();
    vector<int> indegree(n), order;
    for (int u = 0; u < n; ++u) {
        for (int v : graph[u]) ++indegree[v];
    }

    queue<int> q;
    for (int i = 0; i < n; ++i) if (indegree[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : graph[u]) {
            if (--indegree[v] == 0) q.push(v);
        }
    }
    return order;
}

