        bool swapped = false;
        for (int j = 0; j + 1 < (int)a.size() - i; ++j) {
            if (a[j] > a[j + 1]) {
                swap(a[j], a[j + 1]);
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}

