void siftDown(vector<int>& a, int start, int end) {
    int root = start;
    while (root * 2 + 1 <= end) {
        int child = root * 2 + 1;
        if (child + 1 <= end && a[child] < a[child + 1]) ++child;
        if (a[root] >= a[child]) return;
        swap(a[root], a[child]);
        root = child;
    }
}

void heapSort(vector<int>& a) {
    for (int i = (int)a.size() / 2 - 1; i >= 0; --i) siftDown(a, i, (int)a.size() - 1);
    for (int end = (int)a.size() - 1; end > 0; --end) {
        swap(a[0], a[end]);
        siftDown(a, 0, end - 1);
    }
}

